   215→// extractUserPromptAt extracts the user prompt at the given index.
   216→// IDE-injected context tags (like <ide_opened_file>) are stripped from the result.
   217→func extractUserPromptAt(transcript []transcriptLine, idx int) string {
   218→	if idx >= len(transcript) || transcript[idx].Type != transcriptTypeUser {
   219→		return ""
   220→	}
   221→
   222→	var msg userMessage
   223→	if err := json.Unmarshal(transcript[idx].Message, &msg); err != nil {
   224→		return ""
   225→	}
   226→
   227→	// Handle string content
   228→	if str, ok := msg.Content.(string); ok {
   229→		return textutil.StripIDEContextTags(str)
   230→	}
   231→
   232→	// Handle array content (only if it contains text blocks)
   233→	if arr, ok := msg.Content.([]interface{}); ok {
   234→		var texts []string
   235→		for _, item := range arr {
   236→			if m, ok := item.(map[string]interface{}); ok {
   237→				if m["type"] == contentTypeText {
   238→					if text, ok := m["text"].(string); ok {
   239→						texts = append(texts, text)
   240→					}
   241→				}
   242→			}
   243→		}
   244→		if len(texts) > 0 {
   245→			return textutil.StripIDEContextTags(strings.Join(texts, "\n\n"))
   246→		}
   247→	}
   248→
   249→	return ""
   250→}
