   360→// filterTranscriptAfterUUID returns transcript lines after the given UUID
   361→func filterTranscriptAfterUUID(transcript []transcriptLine, uuid string) []transcriptLine {
   362→	if uuid == "" {
   363→		return transcript
   364→	}
   365→
   366→	foundIndex := -1
   367→	for i, line := range transcript {
   368→		if line.UUID == uuid {
   369→			foundIndex = i
   370→			break
   371→		}
   372→	}
   373→
   374→	if foundIndex == -1 || foundIndex == len(transcript)-1 {
   375→		return transcript
   376→	}
   377→
   378→	return transcript[foundIndex+1:]
   379→}
