   427→// extractKeyActions extracts key actions from the transcript for context file
   428→func extractKeyActions(transcript []transcriptLine, maxActions int) []string {
   429→	var keyActions []string
   430→
   431→	for _, line := range transcript {
   432→		if line.Type == transcriptTypeAssistant {
   433→			var msg assistantMessage
   434→			if err := json.Unmarshal(line.Message, &msg); err != nil {
   435→				continue
   436→			}
   437→
   438→			for _, block := range msg.Content {
   439→				if block.Type == "tool_use" {
   440→					var input toolInput
   441→					_ = json.Unmarshal(block.Input, &input) //nolint:errcheck // Best-effort parsing for display purposes
   442→
   443→					detail := input.Description
   444→					if detail == "" {
   445→						detail = input.Command
   446→					}
   447→					if detail == "" {
   448→						detail = input.FilePath
   449→					}
   450→					if detail == "" {
   451→						detail = input.Pattern
   452→					}
   453→
   454→					action := "- **" + block.Name + "**: " + detail
   455→					keyActions = append(keyActions, action)
   456→					if len(keyActions) >= maxActions {
   457→						return keyActions
   458→					}
   459→				}
   460→			}
   461→		}
   462→	}
   463→
   464→	return keyActions
