   485→// FindCheckpointUUID finds the UUID of the message containing the tool_result
   486→// for the given tool_use_id. This is used to find the checkpoint point for
   487→// transcript truncation when rewinding to a task.
   488→// Returns the UUID and true if found, empty string and false otherwise.
   489→func FindCheckpointUUID(transcript []transcriptLine, toolUseID string) (string, bool) {
   490→	for _, line := range transcript {
   491→		if line.Type != transcriptTypeUser {
   492→			continue
   493→		}
   494→
   495→		var msg userMessageWithToolResults
   496→		if err := json.Unmarshal(line.Message, &msg); err != nil {
   497→			continue
   498→		}
   499→
   500→		for _, block := range msg.Content {
   501→			if block.Type == "tool_result" && block.ToolUseID == toolUseID {
   502→				return line.UUID, true
   503→			}
   504→		}
   505→	}
   506→	return "", false
   507→}
