   509→// TruncateTranscriptAtUUID returns transcript lines up to and including the
   510→// line with the given UUID. If the UUID is not found or is empty, returns
   511→// the entire transcript.
   512→//
   513→//nolint:revive // Exported for testing purposes
   514→func TruncateTranscriptAtUUID(transcript []transcriptLine, uuid string) []transcriptLine {
   515→	if uuid == "" {
   516→		return transcript
   517→	}
   518→
   519→	for i, line := range transcript {
   520→		if line.UUID == uuid {
   521→			return transcript[:i+1]
   522→		}
   523→	}
   524→
   525→	// UUID not found, return full transcript
   526→	return transcript
   527→}
