   559→// GetTranscriptPosition reads a transcript file and returns the last UUID and line count.
   560→// Returns empty position if file doesn't exist or is empty.
   561→// Only considers UUIDs from actual messages (user/assistant), not summary rows which use leafUuid.
   562→func GetTranscriptPosition(path string) (TranscriptPosition, error) {
   563→	if path == "" {
   564→		return TranscriptPosition{}, nil
   565→	}
   566→
   567→	file, err := os.Open(path) //nolint:gosec // Reading from controlled transcript path
   568→	if err != nil {
   569→		if os.IsNotExist(err) {
   570→			return TranscriptPosition{}, nil
   571→		}
   572→		return TranscriptPosition{}, fmt.Errorf("failed to open transcript: %w", err)
   573→	}
   574→	defer func() { _ = file.Close() }()
   575→
   576→	var pos TranscriptPosition
   577→	reader := bufio.NewReader(file)
   578→
   579→	for {
   580→		lineBytes, err := reader.ReadBytes('\n')
   581→		if err != nil && err != io.EOF {
   582→			return TranscriptPosition{}, fmt.Errorf("failed to read transcript: %w", err)
   583→		}
   584→
   585→		if len(lineBytes) == 0 {
   586→			if err == io.EOF {
   587→				break
   588→			}
   589→			continue
   590→		}
   591→
   592→		pos.LineCount++
   593→
   594→		// Parse line to extract UUID (only from user/assistant messages, not summaries)
   595→		var line transcriptLine
   596→		if err := json.Unmarshal(lineBytes, &line); err == nil {
   597→			if line.UUID != "" {
   598→				pos.LastUUID = line.UUID
   599→			}
   600→		}
   601→
   602→		if err == io.EOF {
   603→			break
   604→		}
   605→	}
   606→
   607→	return pos, nil
   608→}
